const test=require('node:test');const assert=require('node:assert/strict');const crypto=require('node:crypto');const fs=require('node:fs');const os=require('node:os');const path=require('node:path');const {encrypt,decrypt}=require('../scripts/crypt-bundle');
test('bundle encryption authenticates content and rejects tampering without plaintext output',async(t)=>{const root=fs.mkdtempSync(path.join(os.tmpdir(),'learning-worker-'));t.after(()=>fs.rmSync(root,{recursive:true,force:true}));process.env.LEARNING_WORKER_KEY=crypto.randomBytes(32).toString('base64');const plain=path.join(root,'plain'),encrypted=path.join(root,'encrypted'),roundtrip=path.join(root,'roundtrip');fs.writeFileSync(plain,'candidate evidence');await encrypt(plain,encrypted);assert.doesNotMatch(fs.readFileSync(encrypted).toString('latin1'),/candidate evidence/);await decrypt(encrypted,roundtrip);assert.equal(fs.readFileSync(roundtrip,'utf8'),'candidate evidence');const bytes=fs.readFileSync(encrypted);bytes[30]^=1;fs.writeFileSync(encrypted,bytes);fs.rmSync(roundtrip);await assert.rejects(()=>decrypt(encrypted,roundtrip));assert.equal(fs.existsSync(roundtrip),false);});
